import type { App, FrameContext } from '../app';
import type { Audio } from '../features/audio';
import type { HitTest } from '../features/hitTest';
import type { Portal } from '../features/portal';
import type { Room } from '../features/room';
import type { Toys } from '../features/toys';
import type { HandState, InputEvent } from '../input';
import type { GrabInterceptor, ItemEvents, Items } from '../items';
import type { Interceptor } from '../tools';

/** 操作の分類。メニューの並び順と、ideas.md の分類 (D / C / M) に対応する。 */
export type InteractionCategory = 'delete' | 'duplicate' | 'menu';

/** 操作の実装から使える、ほかの機能 */
export interface InteractionServices {
  app: App;
  audio: Audio;
  room: Room;
  hitTest: HitTest;
  portal: Portal;
  toys: Toys;
}

/**
 * 操作の実装に渡すもの。
 * 入力や物の通知は、必ずここの on... / add... で受け取る。有効な間 (メニューでオンにしていて、MR 中) だけ呼ばれる。
 * app.input.on などに直接登録すると、オフにしても止まらないので使わない。
 */
export interface InteractionContext extends InteractionServices {
  readonly items: Items;
  /** つまみ / 握るの開始・終了 */
  onInput(event: InputEvent, listener: (hand: HandState) => void): void;
  /** 物を持った・離した・消した・複製した */
  onItems<K extends keyof ItemEvents>(event: K, listener: (event: ItemEvents[K]) => void): void;
  /** 近くの物を持とうとしたときに、持つ代わりに別のことをする。処理したら true */
  addGrabInterceptor(interceptor: GrabInterceptor): void;
  /**
   * つまみ / トリガーを、メニュー・物をつかむ・道具より先に横取りする。処理したら true。
   * 何もない所でつまんだときにも呼ばれるので、関係ない入力では false を返すこと。
   */
  addSelectInterceptor(interceptor: Interceptor): void;
}

/**
 * 持っている物を削除・複製する、ひとつの操作方法 (ideas.md の 1 案)。
 * `src/interactions/strategies/` に 1 ファイル 1 案で置き、InteractionFactory を default export すると、
 * 自動で読み込まれ、メニューの「持った物の操作 (試作)」にオン / オフのボタンが出る。
 */
export interface ItemInteraction {
  /** ideas.md の ID。例: 'D1' */
  readonly id: string;
  /** メニューのボタンに出す短い名前 (全角 6 文字程度まで)。ボタンには `${id} ${label}` と出る。 */
  readonly label: string;
  readonly category: InteractionCategory;
  /** 有効になったとき (オンにしたとき、またはオンのまま MR を始めたとき) */
  enable?(): void;
  /** 無効になったとき (オフにしたとき、または MR を終えたとき)。出している物や途中の状態を片付ける。 */
  disable?(): void;
  /** 有効な間、毎フレーム呼ばれる。物の削除・複製は ctx.items.remove / duplicate を通す。 */
  update?(frame: FrameContext): void;
}

export type InteractionFactory = (ctx: InteractionContext) => ItemInteraction;

import * as THREE from 'three';
import type { Item, Items } from '../items';

/** メニュー系の操作 (M1 ～ M3) が並べる、持っている物への操作 */
export interface ItemAction {
  id: 'delete' | 'duplicate';
  label: string;
  /** targets: 対象の物 (ふつうは items.heldBy(hand))。結果の物 (複製なら複製、削除なら空) を返す。 */
  run(items: Items, targets: readonly Item[]): Item[];
}

/** メニューから複製したときに、複製を元からずらす距離 (m) */
const DUPLICATE_OFFSET = 0.12;
const _position = new THREE.Vector3();

export const DELETE_ACTION: ItemAction = {
  id: 'delete',
  label: '消す',
  run(items, targets) {
    for (const item of targets) items.remove(item);
    return [];
  },
};

/** 複製を元の少し上に置く。持っている物でも、複製は持たれていない状態で現れる。 */
export const DUPLICATE_ACTION: ItemAction = {
  id: 'duplicate',
  label: '複製',
  run(items, targets) {
    const copies: Item[] = [];
    for (const item of targets) {
      const copy = items.duplicate(item);
      if (!copy) continue;
      _position.copy(copy.object.position);
      _position.y += DUPLICATE_OFFSET;
      copy.setPose(_position, copy.object.quaternion);
      copies.push(copy);
    }
    return copies;
  },
};

export const ITEM_ACTIONS: readonly ItemAction[] = [DELETE_ACTION, DUPLICATE_ACTION];

// 操作の実装のひな形。_ で始まるファイルは読み込まれないので、コピーして名前を変えて使う。
// ファイル名は `<ideas.md の ID 小文字>-<内容>.ts` (例: d1-shrink.ts)。
import type { InteractionFactory } from '../types';

const create: InteractionFactory = (ctx) => {
  // 例: 持っている物を、もう一方の手で握ると消す。
  ctx.addGrabInterceptor((hand, item) => {
    const other = ctx.app.input.other(hand);
    if (!ctx.items.heldBy(other).includes(item)) return false;
    ctx.audio.click(item.object.position);
    ctx.items.remove(item);
    return true;
  });

  return {
    id: 'X0',
    label: '例',
    category: 'delete',
  };
};

export default create;

import * as THREE from 'three';
import type { App, Feature, FrameContext } from '../app';
import type { HandState } from '../input';
import { CanvasPanel } from '../ui/canvasPanel';

type Group = 'tool' | 'toggle' | 'action' | 'experiment';

interface MenuItem {
  group: Group;
  label: string;
  isActive(): boolean;
  press(): void;
  x: number;
  y: number;
  width: number;
  height: number;
  flashUntil: number;
}

const PANEL_WIDTH = 0.26;
const PIXELS_PER_METER = 2500;
const COLUMNS = 3;
const MARGIN = 12;
const HEADER_HEIGHT = 96;
const SECTION_HEIGHT = 40;
const BUTTON_HEIGHT = 88;
const GROUP_TITLES: Record<Group, string> = { tool: '道具', toggle: '表示', action: '操作', experiment: '持った物の操作 (試作)' };
const GROUPS: Group[] = ['tool', 'toggle', 'action', 'experiment'];

/** 左手からメニューまでの高さ (m) */
const HAND_OFFSET = 0.13;
/**
 * 左手のひらの向きの上向き成分が SHOW を超えたらメニューを出し、HIDE を下回ったら隠す。
 * 境目で点滅しないよう、出す条件と隠す条件に差をつけている。
 */
const PALM_UP_SHOW = Math.cos(THREE.MathUtils.degToRad(50));
const PALM_UP_HIDE = Math.cos(THREE.MathUtils.degToRad(65));
/** 指先がパネルの手前この距離より離れると、次の押下を受け付ける (m) */
const POKE_ARM_DISTANCE = 0.02;
/** レイでメニューを押せる最大距離 (m) */
const RAY_REACH = 2;

const _forward = new THREE.Vector3();

/**
 * 左手の上に浮かぶメニュー。左手のひらを上に向けている間だけ現れる。
 * 反対の手の指先で直接押すか、レイを当ててつまむ / トリガーで押す。
 * 左手が見つからないときは、最後にあった場所 (最初は正面) に留まる。
 */
export class Menu implements Feature {
  readonly name = 'menu';
  /** ボタンが押されたときの通知 (効果音など) */
  onPress: ((position: THREE.Vector3) => void) | null = null;

  private readonly items: MenuItem[] = [];
  private panel: CanvasPanel | null = null;
  /** ボタンの構成が変わったので、パネルを作り直す必要がある */
  private layoutDirty = true;
  /** 見た目が変わったので、描き直す必要がある */
  private dirty = true;
  private toolCount = 0;
  private time = 0;
  private placedInFront = false;
  private palmUp = false;
  private readonly pokeArmed = new Map<HandState, boolean>();

  constructor(private readonly app: App) {
    app.tools.onChange = () => {
      // 道具の選択が変わっただけなら、描き直すだけでよい。
      if (app.tools.list.length !== this.toolCount) this.syncTools();
      this.dirty = true;
    };
    app.tools.addInterceptor((hand) => this.tryRayPress(hand));
    this.syncTools();
  }

  addToggle(
    label: string,
    get: () => boolean,
    set: (value: boolean) => void,
    group: 'toggle' | 'experiment' = 'toggle',
  ): void {
    this.addItem(group, label, get, () => set(!get()));
  }

  addAction(label: string, run: () => void): void {
    this.addItem('action', label, () => false, run);
  }

  start(): void {
    this.placedInFront = false;
    this.palmUp = false;
    this.pokeArmed.clear();
    this.layoutDirty = true;
  }

  end(): void {
    if (this.panel) this.panel.mesh.visible = false;
  }

  update(ctx: FrameContext): void {
    if (this.layoutDirty) this.rebuild();
    const panel = this.panel;
    if (!panel) return;
    this.time = ctx.time;
    this.updatePlacement(panel, ctx);
    if (panel.mesh.visible) this.updatePoke(panel);
    if (this.items.some((item) => item.flashUntil > 0 && item.flashUntil <= ctx.time)) {
      for (const item of this.items) if (item.flashUntil <= ctx.time) item.flashUntil = 0;
      this.dirty = true;
    }
    if (this.dirty) this.draw(panel);
  }

  /** 道具の一覧は Tools が持っているので、道具が増えたらボタンを作り直す。 */
  private syncTools(): void {
    const tools = this.app.tools;
    const others = this.items.filter((item) => item.group !== 'tool');
    this.items.length = 0;
    for (const tool of tools.list) {
      this.addItem(
        'tool',
        tool.label,
        () => tools.active === tool,
        () => tools.setActive(tool),
      );
    }
    this.items.push(...others);
    this.toolCount = tools.list.length;
  }

  private addItem(group: Group, label: string, isActive: () => boolean, press: () => void): void {
    this.items.push({ group, label, isActive, press, x: 0, y: 0, width: 0, height: 0, flashUntil: 0 });
    // ここでは作り直さない。フレーム処理の途中でパネルを差し替えると、古い方に描いてしまう。
    this.layoutDirty = true;
  }

  /** ボタンの数からレイアウトを決め、パネルを作り直す。 */
  private rebuild(): void {
    this.layoutDirty = false;
    const widthPx = PANEL_WIDTH * PIXELS_PER_METER;
    const buttonWidth = (widthPx - MARGIN * (COLUMNS + 1)) / COLUMNS;
    let y = HEADER_HEIGHT;
    for (const group of GROUPS) {
      const items = this.items.filter((item) => item.group === group);
      if (items.length === 0) continue;
      y += SECTION_HEIGHT;
      items.forEach((item, i) => {
        item.x = MARGIN + (i % COLUMNS) * (buttonWidth + MARGIN);
        item.y = y + Math.floor(i / COLUMNS) * (BUTTON_HEIGHT + MARGIN);
        item.width = buttonWidth;
        item.height = BUTTON_HEIGHT;
      });
      y += Math.ceil(items.length / COLUMNS) * (BUTTON_HEIGHT + MARGIN);
    }

    const old = this.panel;
    const panel = new CanvasPanel(PANEL_WIDTH, y / PIXELS_PER_METER, PIXELS_PER_METER);
    // メニューは他の仮想物体に埋もれないよう、最後に深度を無視して描く。
    panel.mesh.renderOrder = 100;
    panel.mesh.material.depthTest = false;
    if (old) {
      panel.mesh.position.copy(old.mesh.position);
      panel.mesh.quaternion.copy(old.mesh.quaternion);
      panel.mesh.visible = old.mesh.visible;
      this.app.scene.remove(old.mesh);
      old.texture.dispose();
      old.mesh.geometry.dispose();
      old.mesh.material.dispose();
    }
    this.app.scene.add(panel.mesh);
    this.panel = panel;
    this.dirty = true;
  }

  private updatePlacement(panel: CanvasPanel, ctx: FrameContext): void {
    const mesh = panel.mesh;
    const left = this.app.input.left;
    if (left.tracked) {
      mesh.position.copy(left.grabPosition);
      mesh.position.y += HAND_OFFSET + panel.height / 2;
      this.palmUp = left.palmNormal.y > (this.palmUp ? PALM_UP_HIDE : PALM_UP_SHOW);
      // 左手で物をつかんでいる間は邪魔なので隠す。
      mesh.visible = this.palmUp && !left.selecting && !left.squeezing;
      this.placedInFront = true;
    } else if (!this.placedInFront) {
      _forward.set(0, 0, -1).applyQuaternion(ctx.headQuaternion).setY(0).normalize();
      mesh.position.copy(ctx.headPosition).addScaledVector(_forward, 0.45);
      mesh.position.y -= 0.25;
      mesh.visible = true;
      this.placedInFront = true;
    } else {
      mesh.visible = true;
    }
    mesh.lookAt(ctx.headPosition);
    mesh.updateMatrixWorld();
  }

  /** メニューを持っている手 (左手が見えていれば左手) では押せない。 */
  private canPress(hand: HandState): boolean {
    const left = this.app.input.left;
    return hand.tracked && !(left.tracked && hand === left);
  }

  /** 指先がパネルの表から裏へ抜けた瞬間に、その位置のボタンを押す。 */
  private updatePoke(panel: CanvasPanel): void {
    for (const hand of this.app.input.hands) {
      if (!this.canPress(hand)) {
        this.pokeArmed.set(hand, false);
        continue;
      }
      const point = panel.project(hand.tipPosition);
      if (!point || point.distance > POKE_ARM_DISTANCE) {
        this.pokeArmed.set(hand, true);
      } else if (point.distance < 0.005 && point.distance > -0.04 && this.pokeArmed.get(hand)) {
        this.pokeArmed.set(hand, false);
        this.pressAt(point.x, point.y, hand);
      }
    }
  }

  private tryRayPress(hand: HandState): boolean {
    const panel = this.panel;
    if (!panel || !panel.mesh.visible || !this.canPress(hand)) return false;
    const point = panel.raycast(hand.rayOrigin, hand.rayDirection);
    if (!point || point.distance > RAY_REACH) return false;
    this.pressAt(point.x, point.y, hand);
    // ボタンの隙間でも、メニュー越しに道具が発動しないよう入力は消費する。
    return true;
  }

  private pressAt(x: number, y: number, hand: HandState): void {
    const item = this.items.find(
      (it) => x >= it.x && x <= it.x + it.width && y >= it.y && y <= it.y + it.height,
    );
    if (!item) return;
    item.flashUntil = this.time + 0.15;
    hand.pulse(0.6, 30);
    this.onPress?.(hand.tipPosition);
    try {
      item.press();
    } catch (error) {
      // ボタンの処理の失敗で、メニューごと止まらないようにする。
      console.error(`[menu] 「${item.label}」の処理に失敗しました`, error);
    }
    this.dirty = true;
  }

  private draw(panel: CanvasPanel): void {
    this.dirty = false;
    const g = panel.context;
    const { width, height } = panel.canvas;
    g.clearRect(0, 0, width, height);
    g.fillStyle = 'rgba(16, 20, 28, 0.88)';
    g.beginPath();
    g.roundRect(0, 0, width, height, 24);
    g.fill();

    g.textBaseline = 'middle';
    g.textAlign = 'left';
    g.fillStyle = '#ffffff';
    g.font = 'bold 30px system-ui, sans-serif';
    g.fillText('MR プレイルーム', MARGIN + 6, 30);
    g.fillStyle = '#a9b4c8';
    g.font = '20px system-ui, sans-serif';
    g.fillText(this.app.tools.active?.hint ?? '', MARGIN + 6, 70, width - MARGIN * 2 - 12);

    let lastGroup: Group | null = null;
    for (const item of GROUPS.flatMap((group) => this.items.filter((it) => it.group === group))) {
      if (item.group !== lastGroup) {
        lastGroup = item.group;
        g.textAlign = 'left';
        g.fillStyle = '#8a94a8';
        g.font = '20px system-ui, sans-serif';
        g.fillText(GROUP_TITLES[item.group], MARGIN + 6, item.y - SECTION_HEIGHT / 2 + 4);
      }
      const active = item.isActive();
      g.fillStyle = item.flashUntil > 0 ? '#ffffff' : active ? '#4f8cff' : '#2a3142';
      g.beginPath();
      g.roundRect(item.x, item.y, item.width, item.height, 14);
      g.fill();
      g.fillStyle = item.flashUntil > 0 ? '#10141c' : '#ffffff';
      g.textAlign = 'center';
      g.font = 'bold 24px system-ui, sans-serif';
      g.fillText(item.label, item.x + item.width / 2, item.y + item.height / 2 + 1, item.width - 12);
    }
    panel.markDirty();
  }
}

